import (
	"net/http"
	"testing"
)

// A priority outside 1..3 must be refused at creation; a stored negative
// priority made GET /v1/reminders panic in priorityName.
func TestCreatePriorityOutOfRange(t *testing.T) {
	c := newClient(t)
	for _, p := range []string{"-1", "-2", "4"} {
		body := `{"text":"x","in":"1h","priority":` + p + `}`
		if code := c.do("tok-ana", http.MethodPost, "/v1/reminders", body, nil); code != http.StatusBadRequest {
			t.Errorf("create priority %s: status %d, want 400", p, code)
		}
	}
	if code := c.do("tok-ana", http.MethodGet, "/v1/reminders", "", nil); code != http.StatusOK {
		t.Errorf("list: status %d, want 200", code)
	}
}
"}

